Next, we write a unit test that uses this stub (production code should test the
error messages too, but for brevity, we’ll leave those out):
func TestProcessorProcessExpressions(t *testing.T) {
p := Processor{MathSolverStub{}}
in := strings.NewReader(`2 + 2 * 10
( 2 + 2 ) * 10
( 2 + 2 * 10`)
data := []float64{22, 40, 0, 0}
for _, d := range data {
result, err :=
p.ProcessExpression(context.Background(), in)
if err != nil {
t.Error(err)

